// Expected digests generated by executing utils.EpusdtSign in the actual upstream
// v1.24.2 checkout (4d88040fd4096e77e8fb9ad2650e775753a977b6), not this adapter.
func TestBepusdtUpstreamSignatureVectors(t *testing.T) {
	for _, tt := range []struct{ body, want string }{
		{`{"order_id":"BE-test","amount":10.00,"fiat":"CNY","trade_type":"usdt.trc20","timeout":1200,"notify_url":"https://shop.example/payments/callback/be?channel_id=3","redirect_url":"https://shop.example/payment/ORDER-1","name":"订单 ORDER-1"}`, "f0420bc65062e18f18c68e9b3c69e06a"},
		{`{"trade_id":"T-test","order_id":"BE-test","amount":10.00,"actual_amount":"1.4231","token":"T-address","block_transaction_id":"block-123","status":2}`, "69d8242aeac693888567f99c190f771b"},
		{`{"amount":1000000.00,"status":2,"empty":"","nil":null,"zero":0,"bool":false}`, "8cd14d8e6a9934e06e160b633002c8cb"},
	} {
		got, err := bepusdtSign([]byte(tt.body), "contract-test-token")
		if err != nil || got != tt.want {
			t.Fatalf("signature %s want %s: %v", got, tt.want, err)
		}
	}
}

func TestBepusdtWebhookUpstreamFixture(t *testing.T) {
	cfg := json.RawMessage(`{"api_url":"https://pay.example","api_token":"contract-test-token"}`)
	body := []byte(`{"trade_id":"T-test","order_id":"BE-test","amount":10.00,"actual_amount":"1.4231","token":"T-address","block_transaction_id":"block-123","status":2,"signature":"69d8242aeac693888567f99c190f771b"}`)
	b := NewBepusdt()
	f, err := b.ParseWebhook(nil, body, cfg)
	if err != nil || !f.Success || f.Amount != 1000 || f.Currency != "CNY" || f.GatewayOrderRef != "BE-test" || f.OrderNo != "" {
		t.Fatalf("fact %+v: %v", f, err)
	}
	for _, bad := range []string{strings.Replace(string(body), "10.00", "10.01", 1), strings.Replace(string(body), "1.4231", "10.00", 1), strings.Replace(string(body), "BE-test", "BE-forged", 1)} {
		if _, err := b.ParseWebhook(nil, []byte(bad), cfg); err == nil {
			t.Fatal("accepted tampered callback")
		}
	}
	if _, ok := any(b).(port.Capturer); ok {
		t.Fatal("unsigned cashier info must not be a merchant query API")
	}
}

func TestBepusdtCreateProtocol(t *testing.T) {
	for _, chain := range []string{"usdt.trc20", "usdt.erc20", "usdt.bep20"} {
		t.Run(chain, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.Method != "POST" || r.URL.Path != "/api/v1/order/create-transaction" {
					t.Errorf("wrong endpoint %s %s", r.Method, r.URL.Path)
				}
				body, _ := io.ReadAll(r.Body)
				var m map[string]any
				_ = json.Unmarshal(body, &m)
				sig, _ := bepusdtSign(body, "test-token")
				if sig != m["signature"] || m["fiat"] != "CNY" || m["trade_type"] != chain || m["amount"] != 10.0 || m["order_id"] != "BE-test" {
					t.Errorf("invalid protocol request")
				}
				if m["timeout"].(float64) < 180 {
					t.Error("upstream will silently use default timeout")
				}
				fmt.Fprintf(w, `{"status_code":200,"data":{"order_id":"BE-test","trade_id":"trade-1","fiat":"CNY","trade_type":%q,"amount":"10","status":1,"payment_url":"https://pay.example/pay/trade-1","expiration_time":170}}`, chain)
			}))
			defer srv.Close()
			cfg, _ := json.Marshal(BepusdtConfig{APIURL: srv.URL, APIToken: "test-token", TradeType: chain, Timeout: 180})
			info, err := NewBepusdt().CreatePayment(context.Background(), port.CreatePaymentRequest{GatewayOrderRef: "BE-test", Amount: 1000, Deadline: time.Now().Add(180 * time.Second), Config: cfg, ReturnURL: "https://shop.example/return", NotifyBaseURL: "https://shop.example/notify"})
			if err != nil || info.ChannelOrderNo != "trade-1" || string(info.Payload) != "https://pay.example/pay/trade-1" || time.Until(info.Deadline) > 171*time.Second {
				t.Fatalf("info %+v: %v", info, err)
			}
		})
	}
}

func TestBepusdtRejectGatewayMismatch(t *testing.T) {
	good := `{"status_code":200,"data":{"order_id":"BE-test","trade_id":"trade-1","fiat":"CNY","trade_type":"usdt.trc20","amount":"10","status":1,"payment_url":"https://pay.example/pay/trade-1","expiration_time":100}}`
	for _, body := range []string{`{"status_code":400,"message":"private upstream details"}`, strings.Replace(good, `"10"`, `"9.99"`, 1), strings.Replace(good, "BE-test", "OTHER", 1), strings.Replace(good, "CNY", "USD", 1), strings.Replace(good, "usdt.trc20", "usdt.bep20", 1), strings.Replace(good, `"status":1`, `"status":3`, 1), strings.Replace(good, `"expiration_time":100`, `"expiration_time":18446744073709551600`, 1), strings.Replace(good, "https://pay.example/pay/trade-1", "javascript:alert(1)", 1)} {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, body) }))
		cfg, _ := json.Marshal(BepusdtConfig{APIURL: srv.URL, APIToken: "test-token"})
		_, err := NewBepusdt().CreatePayment(context.Background(), port.CreatePaymentRequest{GatewayOrderRef: "BE-test", Amount: 1000, Deadline: time.Now().Add(300 * time.Second), Config: cfg})
		srv.Close()
		if err == nil {
			t.Fatalf("accepted %s", body)
		}
	}
}

func TestBepusdtConfigAndExactAmounts(t *testing.T) {
	for _, extra := range []string{`,"timeout":179`, `,"timeout":3601`, `,"trade_type":"tron"`, `,"fiat":"USD"`, `,"target_currency":"USD"`, `,"currency":false`} {
		if err := NewBepusdt().ValidateConfig(json.RawMessage(`{"api_url":"https://pay.example","api_token":"token"` + extra + `}`)); err == nil {
			t.Fatalf("accepted %s", extra)
		}
	}
	for _, raw := range []string{`0`, `-1`, `0.001`, `"1.0001"`, `1e99`, `1e-999999999`, `true`, `null`, `""`, `"2abc"`} {
		if _, err := bepusdtAmount([]byte(raw)); err == nil {
			t.Fatalf("accepted amount %s", raw)
		}
	}
	for _, raw := range []string{`10.00`, `"10.00"`, `1e1`} {
		if got, err := bepusdtAmount([]byte(raw)); err != nil || got != 1000 {
			t.Fatalf("%s: %d %v", raw, got, err)
		}
	}
}

// Optional source-contract run: point at the isolated v1.24.2 SignVerify +
// CreateTransaction harness, seeded with test wallets/rates and no chain monitor.
func TestBepusdtNativeSourceContract(t *testing.T) {
	gateway := os.Getenv("BEPUSDT_SOURCE_TEST_URL")
	if gateway == "" {
		t.Skip("requires isolated upstream source harness")
	}
	for _, chain := range []string{"usdt.trc20", "usdt.erc20", "usdt.bep20"} {
		t.Run(chain, func(t *testing.T) {
			cfg, _ := json.Marshal(BepusdtConfig{APIURL: gateway, APIToken: "contract-test-token", TradeType: chain})
			req := port.CreatePaymentRequest{GatewayOrderRef: fmt.Sprintf("source-%d", time.Now().UnixNano()), Amount: 1000, Deadline: time.Now().Add(600 * time.Second), Subject: "source contract", ReturnURL: "https://example.com/return", NotifyBaseURL: "https://example.com/notify", Config: cfg}
			first, err := NewBepusdt().CreatePayment(context.Background(), req)
			if err != nil {
				t.Fatal(err)
			}
			// Even a larger timeout must not rebuild the original trade or refresh expiry.
			req.Deadline = req.Deadline.Add(10 * time.Minute)
			second, err := NewBepusdt().CreatePayment(context.Background(), req)
			if err != nil {
				t.Fatal(err)
			}
			if second.ChannelOrderNo != first.ChannelOrderNo || second.Deadline.Sub(first.Deadline) > time.Second {
				t.Fatalf("upstream reuse changed: first=%+v second=%+v", first, second)
			}
		})
	}
}
